&lt;img loading=&#34;lazy&#34; src=&#34;https://cdn.discordapp.com/attachments/1150812822012440648/1183770667590635590/Texas_3k.PNG?ex=65898b58&amp;amp;is=65771658&amp;amp;hm=df2653329521a108508e0103d9dd3cfef0f1be17d856822a4079a766acad9d23&amp;amp;&#34; alt=&#34;&#34; width=&#34;800px&#34; /&gt;&lt;/p&gt;
